// processor.h
typedef struct block_result {
    int block_id;
    int status;
    char* error_msg;
} block_result_t;

typedef void (*result_callback)(block_result_t result, void* user_data);

// Processes blocks asynchronously via thread pool
// user_data is passed through to the callback
// Returns JSON string allocated with malloc (caller must free)
char* process_blocks_async(
    const uint8_t* blocks[],  // Array of block data pointers
    size_t* block_sizes,      // Array of block sizes
    size_t block_count,       // Number of blocks
    result_callback callback, // Called for each block result
    void* user_data           // User-provided context
);

// Request cancellation (non-blocking)
void request_cancellation(void* session_handle);

